const out = [];
for (const item of items) {
  const r = item.json;
  if (!r.due_date || String(r.status || '').toLowerCase() === 'paid') continue;
  const due = new Date(r.due_date);
  if (isNaN(due.getTime())) continue;
  const days = Math.floor((Date.now() - due.getTime()) / 86400000);
  if (days <= 0) continue;
  const bucket = days <= 7 ? 1 : (days <= 21 ? 2 : 3);
  out.push({ json: Object.assign({}, r, { days_overdue: days, bucket }) });
}
return out;

const src = $json;
let body = '';
try { body = $json.choices[0].message.content.trim(); } catch (e) {}
if (!body) body = 'Hi ' + (src.client_name || 'there') + ',\n\nJust a friendly reminder that invoice ' + src.invoice_number + ' for ' + (src.currency || 'USD') + ' ' + src.amount + ' is now ' + src.days_overdue + ' days overdue. Could you let me know when payment will be made?\n\nMany thanks!';
return { json: Object.assign({}, src, {
  subject: 'Reminder: Invoice ' + src.invoice_number + (src.bucket === 3 ? ' - final notice' : ''),
  body, sent_at: new Date().toISOString(),
}) };
